bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 41
printf 'POLL_IMAGE=%s\n' "$(docker inspect "$cid" --format '{{.Config.Image}}')"
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';
import pg from 'pg';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {readPrivateToken} from './src/runtime/config.mjs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
const env=process.env;
console.log('RUNTIME_FLAGS='+JSON.stringify({saleMode:env.VIDEO_SALE_MODE??null,localApi:env.VIDEOBOT_LOCAL_API_URL??null,localMediaRootConfigured:!!env.VIDEOBOT_LOCAL_MEDIA_ROOT}));
const pool=new pg.Pool({host:env.VIDEOBOT_DB_HOST,user:env.VIDEOBOT_DB_USER,database:env.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:4500});
const net=createCreatorTelegramFetch();
try{
 const rows=(await pool.query("SELECT l.listing_id,l.revision,l.status,l.price_stars,l.sample_duration_seconds,l.paid_video_file_id,l.thumbnail_file_id,l.sample_file_id,r.delivery_key,r.sale_mode,r.status AS receipt_status,r.free_message_ids,r.paid_message_id FROM videobot_listings l LEFT JOIN videobot_post_receipts r ON l.listing_id=r.listing_id ORDER BY l.updated_at DESC,l.listing_id DESC LIMIT 16")).rows;
 const purchases=(await pool.query("SELECT delivery_key,COUNT(*)::int AS buyers FROM videobot_stars_ledger WHERE kind='paid' GROUP BY delivery_key ORDER BY buyers DESC LIMIT 12")).rows;
 console.log('PURCHASE_KEYS='+JSON.stringify(purchases));
 const api=createTelegramBotApi({token:readPrivateToken(env.VIDEOBOT_TELEGRAM_TOKEN_FILE),fetchImpl:net.fetch,timeoutMs:25000,baseUrl:env.VIDEOBOT_LOCAL_API_URL??'https://api.telegram.org'});
 let j=0;
 for(const row of rows){
   const result={listing:row.listing_id,rev:row.revision,status:row.status,mode:row.sale_mode??null,receipt:row.receipt_status??null,hasThumbnail:!!row.thumbnail_file_id,hasSample:!!row.sample_file_id,hasMain:!!row.paid_video_file_id,sampleSec:row.sample_duration_seconds,freeCount:row.free_message_ids?.length??0,paidMessagePresent:row.paid_message_id!=null};
   if(row.paid_video_file_id && j++<8)try{const f=await api('getFile',{file_id:row.paid_video_file_id});result.fileSizeBytes=f?.file_size??null;result.filePathAvailable=!!f?.file_path;}catch(e){result.fileError=String(e?.message??e).replace(/([A-Za-z0-9_-]{32,})/g,'[id]').slice(0,150)}
   console.log('LISTING='+JSON.stringify(result));
 }
}finally{await pool.end();await net.close();}
NODE
